function sync(g){desiredPos=g.players.map(p=>p.pos);active=g.active;won=g.phase==='won';board.beacons.forEach((b,i)=>{b.orb.material.emissiveIntensity=g.beacons[i]?1.2:.05;b.ring.material.color.set(g.beacons[i]?b.tint:'#69717d');});board.tiles.forEach((tile,i)=>{tile.material.emissive.set(i===g.players[g.active].pos?(g.active===0?'#3fc8ff':'#ff7a45'):'#000000');tile.material.emissiveIntensity=i===g.players[g.active].pos?.55:0;});}
